import type {
  PreparedBuilding,
  TerrainGrid,
} from '../../src/terrain/types';

export interface GridOptions {
  halfSizeM?: number;
  spacingM?: number;
  elevation?: (eastM: number, northM: number) => number;
  originLatDeg?: number;
  originLonDeg?: number;
}

/**
 * Synthetic ENU terrain grid. Cell (0,0) is the north-west corner; the
 * observer is at (0, 0). Elevations are generated by a pure callback so tests
 * can describe a flat plane, a uniform slope or a ridge exactly.
 */
export function makeGrid(options: GridOptions = {}): TerrainGrid {
  const halfSizeM = options.halfSizeM ?? 5_000;
  const spacingM = options.spacingM ?? 10;
  const elevation = options.elevation ?? (() => 0);
  const width = Math.round((2 * halfSizeM) / spacingM) + 1;
  const height = width;
  const elevations = new Float32Array(width * height);
  for (let row = 0; row < height; row++) {
    const northM = halfSizeM - row * spacingM;
    for (let col = 0; col < width; col++) {
      const eastM = -halfSizeM + col * spacingM;
      elevations[row * width + col] = elevation(eastM, northM);
    }
  }
  return {
    zoom: 14,
    width,
    height,
    elevations,
    spacingM,
    spacingEastM: spacingM,
    spacingNorthM: spacingM,
    eastOriginM: -halfSizeM,
    northOriginM: halfSizeM,
    originLatDeg: options.originLatDeg ?? 45,
    originLonDeg: options.originLonDeg ?? 25,
    observerGroundElevationM: elevation(0, 0),
    tileRange: { xMin: 0, xMax: 0, yMin: 0, yMax: 0 },
    bbox: { south: 44.9, west: 24.9, north: 45.1, east: 25.1 },
    requestedTiles: 1,
    cachedTiles: 0,
    networkTiles: 1,
    failedTiles: 0,
    createdAt: 1,
  };
}

export function makeBuilding(options: {
  id?: number;
  eastM?: number;
  northM?: number;
  widthM?: number;
  depthM?: number;
  heightM?: number;
  baseElevationM?: number;
}): PreparedBuilding {
  const id = options.id ?? 1;
  const eastM = options.eastM ?? 0;
  const northM = options.northM ?? 100;
  const widthM = options.widthM ?? 20;
  const depthM = options.depthM ?? 4;
  const halfW = widthM / 2;
  const halfD = depthM / 2;
  const ringEnu = [
    { eastM: eastM - halfW, northM: northM - halfD },
    { eastM: eastM + halfW, northM: northM - halfD },
    { eastM: eastM + halfW, northM: northM + halfD },
    { eastM: eastM - halfW, northM: northM + halfD },
  ];
  return {
    id,
    ringEnu,
    minEastM: eastM - halfW,
    maxEastM: eastM + halfW,
    minNorthM: northM - halfD,
    maxNorthM: northM + halfD,
    baseElevationM: options.baseElevationM ?? 0,
    heightM: options.heightM ?? 2,
    heightSource: 'height',
    tags: {},
  };
}

export const FLAT_POINT = {
  latitudeDeg: 45,
  longitudeDeg: 25,
  groundElevationM: 0,
  eyeHeightM: 1.7,
};
